import{_ as t,o as s,c as a,ag as i}from"./chunks/framework.BPmc_f4o.js";const g=JSON.parse('{"title":"Operator Mode","description":"","frontmatter":{},"headers":[],"relativePath":"guides/operator-mode.md","filePath":"guides/operator-mode.md"}'),o={name:"guides/operator-mode.md"};function n(r,e,h,d,l,c){return s(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="operator-mode" tabindex="-1">Operator Mode <a class="header-anchor" href="#operator-mode" aria-label="Permalink to &quot;Operator Mode&quot;">​</a></h1><p>Operator mode boots Muxit straight into a dashboard — no file explorer, no code editor, no settings. It is for the moment a rig stops being something you are building and becomes something someone <em>runs</em>: a bench appliance with a touchscreen, a station handed to a colleague, a long unattended soak test, a demo you don&#39;t want a stray click to derail.</p><div class="tip custom-block"><p class="custom-block-title">What it protects</p><p>Operator mode is a <strong>write gate</strong>, not a read gate. When it is on, the server refuses every message that would <em>author</em> something — edit a script or connector, change config, install a driver, move the safety level, drive the AI — from <strong>every</strong> anonymous client, not just the operator shell. Reads pass, and so do the four writes a dashboard is built from.</p><p>It does not narrow <em>device control</em>: an operator can call anything a dashboard button could have called. Bounding that is the <a href="/guides/safety.html">safety level</a>&#39;s job, together with a connector&#39;s <code>hide</code> / <code>expose</code> lists. Operator mode stops the test being <strong>changed</strong>; the safety level bounds what running it may <strong>do</strong>.</p><p>Add <a href="/guides/accounts.html">accounts</a> and the station can tell people apart: operators are held to the gate and named in the audit trail, while an engineer signs in to lift it for their own session.</p></div><div class="warning custom-block"><p class="custom-block-title">Pro tier and above</p><p>Operator mode — the locked station, its capability gate and the read-only chat — needs a <strong>Pro</strong> license or higher, and so do <a href="/guides/accounts.html">accounts</a>. A station whose license does not cover it starts as an ordinary Muxit install: the mode simply does not engage, and the startup banner says so.</p><p>The audit trail naming <em>which</em> operator did what is a separate <strong>Lab</strong> feature — Pro gets the access control, Lab gets the paper trail.</p><p><strong>A station that has been licensed keeps operator mode for 60 days</strong> if the license stops checking out — see <em>If the license lapses</em> below. A station that was never licensed simply never engages the mode.</p></div><h2 id="setting-it-up" tabindex="-1">Setting it up <a class="header-anchor" href="#setting-it-up" aria-label="Permalink to &quot;Setting it up&quot;">​</a></h2><p>The folder <em>is</em> the configuration. Put the dashboards and scripts an operator should have into an <code>operator/</code> sub-folder, and that set becomes their whole world:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>workspace/</span></span>
<span class="line"><span>  dashboards/operator/       ← dashboards operators can see</span></span>
<span class="line"><span>    station.dashboard.json</span></span>
<span class="line"><span>  scripts/operator/          ← scripts operators can run</span></span>
<span class="line"><span>    run-test.js</span></span>
<span class="line"><span>    calibrate.js</span></span></code></pre></div><p>There is no manifest, allowlist or permissions screen to keep in sync. Add a file and it appears; delete it and it&#39;s gone. Everything outside those two folders stays invisible in operator mode.</p><p>Muxit already keys scripts and dashboards by their path relative to the workspace folder, so <code>scripts/operator/run-test.js</code> is simply the script named <code>operator/run-test</code> — it shows up in your normal Scripts panel and runs the same way it always did.</p><h2 id="turning-it-on" tabindex="-1">Turning it on <a class="header-anchor" href="#turning-it-on" aria-label="Permalink to &quot;Turning it on&quot;">​</a></h2><p>Two ways in, and they are deliberately different in strength.</p><h3 id="per-install-—-the-anonymous-visitor-policy" tabindex="-1">Per install — the anonymous-visitor policy <a class="header-anchor" href="#per-install-—-the-anonymous-visitor-policy" aria-label="Permalink to &quot;Per install — the anonymous-visitor policy&quot;">​</a></h3><p>Operator mode is not a switch of its own. It is what happens when the <a href="/guides/accounts.html">accounts</a> policy for <strong>anonymous visitors</strong> is <strong>Dashboards only</strong>: every browser that has not signed in gets the operator shell, and the server enforces the gate for it. Set it under <strong>Settings › Accounts › Anonymous visitors</strong>, or in <code>workspace/config/accounts.json</code>:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;anonymous&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;dashboard&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;accounts&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: []</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>It takes effect immediately, no restart. A file with no accounts listed, as above, is an anonymous kiosk: everyone is an operator and nobody is asked who they are. Add an engineer or admin account and that person can sign in on the station to service it, and change the policy back from Settings; with no such account, the way out is editing the file and restarting.</p><p><strong>Settings › Accounts › Operator dashboards</strong> lists what the station has and picks the one to open on start (stored as <code>ui.operatorDashboard</code> in <code>server.json</code>). Leave it on <em>First dashboard found</em> and a single-dashboard station needs nothing beyond the policy.</p><h3 id="per-device-—-view-operator" tabindex="-1">Per device — <code>?view=operator</code> <a class="header-anchor" href="#per-device-—-view-operator" aria-label="Permalink to &quot;Per device — \`?view=operator\`&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://192.168.1.40:8765/?view=operator</span></span></code></pre></div><p>The station&#39;s touchscreen runs the operator shell while your laptop keeps the full interface against the same server. The choice is remembered in that browser, so a kiosk reopened without the query string still comes up in operator mode. <code>?view=full</code> clears it, as does the <strong>Exit</strong> button in the header.</p><p>This is a convenience, not a lock — anyone can edit the URL back, and <strong>the server does not enforce anything for a <code>?view=operator</code> browser</strong>. It carries no identity the server could trust, so it changes only what that browser renders. Use it when you want a tidy panel on the shop floor while you keep the full UI on your laptop; use the policy when it actually has to hold.</p><p>When the policy is <code>dashboard</code>, it wins, and the Exit button disappears.</p><h2 id="what-a-locked-station-accepts" tabindex="-1">What a locked station accepts <a class="header-anchor" href="#what-a-locked-station-accepts" aria-label="Permalink to &quot;What a locked station accepts&quot;">​</a></h2><p>With the anonymous-visitor policy on <code>dashboard</code>:</p><table tabindex="0"><thead><tr><th>Passes</th><th>Refused</th></tr></thead><tbody><tr><td>Live state, streams, connector and driver listings</td><td>Editing scripts, connectors, dashboards or config</td></tr><tr><td>Reading dashboards</td><td>The immediate window (<code>scripts.execute</code>)</td></tr><tr><td><code>connector.call</code> — every button, toggle, slider and knob</td><td>Renaming connectors, changing visibility, reloading</td></tr><tr><td>Starting scripts <strong>in the <code>operator/</code> folder</strong></td><td>Starting anything outside <code>operator/</code></td></tr><tr><td>Stopping any running script, including Stop All</td><td>Marketplace, driver installs, updates, licensing</td></tr><tr><td>Answering <code>ask.*</code> prompts</td><td>Changing the safety level</td></tr><tr><td>Reading the current safety level</td><td>The audit log, agents, vision teaching</td></tr><tr><td>AI chat, on dashboards that turn it on</td><td>AI memory, credits and prompt introspection</td></tr></tbody></table><p>Refusals come back as <code>OPERATOR_MODE_RESTRICTED</code> and name the way out.</p><p>The <strong>editor API</strong> (<code>/api/editor/*</code>) and the <strong>MCP endpoint</strong> (<code>/mcp</code>) are both refused for anonymous callers and operators, and both stay registered, so a request carrying an engineer&#39;s or admin&#39;s account token passes. MCP&#39;s tools include <code>write_script</code> and <code>write_connector_config</code>, so an MCP client on a locked station needs that token; without one, set the policy back to <code>full</code>.</p><p><strong>The safety level is pinned</strong> by consequence, not by a separate setting: whatever the engineer last selected persists in <code>safety.state.level</code>, and <code>safety.setLevel</code> is refused, so an operator cannot escalate to Unrestricted. Set the level you want before turning operator mode on.</p><p>Because <code>config.set</code> and the accounts API are both refused, an operator <strong>cannot turn operator mode off from the UI</strong>. Either sign in as an admin and change the policy under Settings › Accounts, or edit <code>&quot;anonymous&quot;</code> in <code>workspace/config/accounts.json</code> and restart.</p><h2 id="who-is-at-the-station" tabindex="-1">Who is at the station <a class="header-anchor" href="#who-is-at-the-station" aria-label="Permalink to &quot;Who is at the station&quot;">​</a></h2><p>Out of the box a locked station is an <strong>anonymous operator station</strong>: everyone who connects is an operator, nobody is asked who they are.</p><p>Add <a href="/guides/accounts.html">accounts</a> and the station can tell people apart:</p><ul><li>The dashboard stays viewable by anyone. Under the <code>dashboard</code> policy anyone may press its controls and signing in only adds a name. If every press must carry a name, use the <code>login</code> policy instead and open the floor screen with <code>?view=operator</code>: it shows the dashboard, and pressing a control raises the PIN pad over it.</li><li><strong>Sign in</strong>, <strong>Switch</strong> and <strong>Sign out</strong> live in the shell&#39;s header. A shift change never takes the dashboard down.</li><li>A signed-in <strong>operator</strong> is held to the gate and named in the audit trail.</li><li>A signed-in <strong>engineer or admin</strong> gets the full interface — the server lifts the gate for their connection only — which is how a locked station is serviced without editing config and restarting.</li><li>A session that idles out mid-shift raises the sign-in panel rather than leaving dead controls behind. Whatever was refused is <strong>not</strong> retried for you after signing in; press it again deliberately.</li></ul><p>Accounts are managed under <strong>Settings › Accounts</strong> by an admin, and the first admin is created there too. Everything about roles, PINs, the policy and recovery is in the <a href="/guides/accounts.html">Accounts guide</a>.</p><div class="tip custom-block"><p class="custom-block-title">Who gets the record</p><p>Every tier that can run operator mode gets the access control. The <strong>audit trail</strong> that records <em>which</em> operator did what is a separate, higher-tier feature — the identity always flows, and the audit log simply does not write on tiers without it. See <a href="/guides/safety.html#audit-log">Safety</a>.</p></div><h2 id="ai-chat-optional" tabindex="-1">AI chat (optional) <a class="header-anchor" href="#ai-chat-optional" aria-label="Permalink to &quot;AI chat (optional)&quot;">​</a></h2><p>Chat is switched on <strong>per dashboard</strong>, not per station: open the dashboard in the editor and tick <strong>Operator chat</strong> under its Dashboard settings, which writes <code>&quot;chat&quot;: true</code> at the top level of the dashboard file. That dashboard then shows an <strong>Ask</strong> button in the operator shell, while a wall display on the same station stays clean. Only dashboards under <code>operator/</code> count — the flag on an engineer&#39;s dashboard does nothing. The button opens a small panel where the operator can ask questions about the rig:</p><blockquote><p><em>&quot;Why did unit 4471 fail?&quot;</em><em>&quot;What does the chiller&#39;s E-042 code mean?&quot;</em><em>&quot;Is the supply actually at 5 V right now?&quot;</em></p></blockquote><p>The assistant is <strong>read-only</strong>, enforced server-side. It may read device state and connector schemas, look at scripts and their output, read dashboards, and search the docs and any instrument manuals you have loaded. It may not write a property, call an action, start or stop a script, or author anything — those tools are never offered to the model, and are refused if it calls one anyway.</p><p>That narrowing follows <strong>the person, not the station</strong>. Sign in as an engineer or admin and the chat is the ordinary Muxit assistant with its full toolset — it can edit connectors and scripts, change settings and drive hardware, on a locked station just as it would anywhere else, because lifting the gate for that connection is what the account is for. A signed-in operator gets the read-only assistant even on a station that never turned operator mode on.</p><p>Starting a test is deliberately not on that list. A dashboard button is a person&#39;s decision with a unit in front of them; a model deciding on its own to start a run is not the same thing. Ask it what happened, not to do something.</p><p>Chat is off by default and independent of the rest of operator mode — turning it on does not widen anything else. It still needs an AI provider configured, and the Muxit-managed provider is tier-gated as usual.</p><h2 id="if-the-license-lapses" tabindex="-1">If the license lapses <a class="header-anchor" href="#if-the-license-lapses" aria-label="Permalink to &quot;If the license lapses&quot;">​</a></h2><p>The tier is confirmed by a signed proof that is only good for 24 hours, and the server refreshes it on the same cadence. So the usual reason a station stops being Pro is <strong>not</strong> an unpaid invoice — it is a network problem: a firewall change, a proxy that started intercepting TLS, a VLAN that went down overnight.</p><p>Losing operator mode in that moment would be the worst possible failure: the station would go back to showing the full interface mid-shift — the editor, settings and every connector, to whoever is standing at it — and nobody would be told. So it doesn&#39;t happen that way.</p><p><strong>A machine that has held a Pro license keeps operator mode for 60 days</strong> after the last time its license checked out, and says so every day it does:</p><ul><li>a warning on the startup banner,</li><li>a banner across the top of the operator shell, counting down the days,</li><li>a notice on the sign-in screen, where an engineer will see it,</li><li>the same warning in Settings › Server › Operator Mode and Settings › Accounts.</li></ul><p>Each of those names <strong>which of the two problems</strong> it is, because they have completely different fixes:</p><table tabindex="0"><thead><tr><th>What happened</th><th>What you see</th><th>What to do</th></tr></thead><tbody><tr><td>Muxit can&#39;t reach the license service</td><td><em>&quot;Muxit cannot reach the license service to confirm this machine&#39;s subscription&quot;</em></td><td>Check the machine&#39;s internet connection. If the subscription is active, nothing else is needed</td></tr><tr><td>The subscription ended</td><td><em>&quot;This machine&#39;s Muxit subscription has ended&quot;</em></td><td>Renew the subscription</td></tr></tbody></table><p>A subscription that is <strong>cancelled or revoked</strong> — where the license service answers and says no, rather than not answering — gets no grace: operator mode becomes unavailable at that point.</p><p><a href="/guides/accounts.html">Accounts</a> and the <strong>Lab audit trail</strong> work the same way, for the same reason: a station whose sign-in policy silently stopped applying, or traceability that stops without anyone noticing, is worse for a compliance customer than either costing money.</p><p><strong>The Pro safety levels are not part of that grace.</strong> While the license is not confirmed, a station set to Assisted or Active runs at <strong>Observe</strong>: the dashboard still works, but every write and action is simulated and nothing reaches the hardware. The station says so — a <strong>Hardware control is off</strong> banner under the status strip, an amber <strong>Observe · license</strong> chip, and a line on the startup banner — naming the same two causes as the table above; on the operator shell it tells the operator to fetch an administrator. The chosen level is kept and comes back by itself the moment the license checks out again, so a station that was switched off over a long weekend is back at its level seconds after it reaches the license service. See <a href="/guides/safety.html#when-the-license-no-longer-covers-your-level">Safety</a>.</p><p>After 60 days operator mode becomes unavailable and the station behaves as an ordinary Muxit install. A machine that <em>never</em> held the license gets no grace at all — the mode simply never engages.</p><div class="tip custom-block"><p class="custom-block-title">Air-gapped stations</p><p>This is a grace period, not an offline licensing mode. A station that can never reach the license service keeps operator mode for 60 days from its last successful check, and loses it after that. If you need a permanently disconnected cell, talk to us about offline activation rather than relying on this.</p></div><h2 id="what-the-operator-sees" tabindex="-1">What the operator sees <a class="header-anchor" href="#what-the-operator-sees" aria-label="Permalink to &quot;What the operator sees&quot;">​</a></h2><ul><li>The dashboard, full-bleed and read-only — widgets can&#39;t be dragged or resized out of shape mid-run.</li><li>A dashboard selector, if there is more than one.</li><li>Live connection state.</li><li>The status strip, with running scripts and <strong>Stop All</strong>.</li><li>Any <code>ask.*</code> prompt a script is waiting on, as a modal.</li></ul><p>That last one matters. A script blocked on <code>ask.confirm()</code> with nothing on screen to answer it just looks frozen, so the operator shell surfaces prompts directly instead of inside the chat panel.</p><p><code>ask.text</code> is worth knowing about here: a USB barcode scanner is just a keyboard, and the prompt&#39;s input is focused automatically, so</p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> serial</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ask.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">text</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;Scan serial number&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><p>works by scanning, with no extra setup.</p><h2 id="recording-results" tabindex="-1">Recording results <a class="header-anchor" href="#recording-results" aria-label="Permalink to &quot;Recording results&quot;">​</a></h2><p>Operator mode has no built-in test-record store. Scripts write their own results through a <a href="/reference/drivers/file-access.html">FileAccess connector</a>:</p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> results</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> connector</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;files&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">).</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">openText</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;results.csv&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> serial</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ask.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">text</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;Scan serial number&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> v</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> connector</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;dut&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">).voltage;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> pass</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> v </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 4.9</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &amp;&amp;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> v </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 5.1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">results.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">append</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">([</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">timestamp</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(), serial, v, pass </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">?</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;PASS&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> :</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;FAIL&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]);</span></span></code></pre></div><p>Open that CSV in a tab and the chart refreshes as rows land.</p><h2 id="no-operator-dashboard" tabindex="-1">No operator dashboard? <a class="header-anchor" href="#no-operator-dashboard" aria-label="Permalink to &quot;No operator dashboard?&quot;">​</a></h2><p>If operator mode is on but <code>dashboards/operator/</code> is empty, Muxit refuses to enter and shows setup instructions instead. That is on purpose: a blank panel in front of someone with no way to fix it is worse than an explanation of what to create.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="/guides/accounts.html">Accounts</a> — admin, engineer and operator sign-in</li><li><a href="/guides/dashboards.html">Dashboards</a> — building the dashboard operators will use</li><li><a href="/guides/scripts.html">Scripts</a> — <code>ask.*</code> prompts and script structure</li><li><a href="/guides/remote-access.html">Remote Access</a> — reaching a station from another machine</li><li><a href="/reference/configuration.html">Configuration</a> — the full <code>ui</code> section</li></ul>`,67)])])}const u=t(o,[["render",n]]);export{g as __pageData,u as default};
